/// A refusal: which guard, and the message for the model (correction first).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Denial {
    pub rule: RuleRef,
    pub reason: String,
}

fn deny(guard: &str, reason: String) -> Denial {
    Denial {
        rule: RuleRef::guard(guard),
        reason,
    }
}

// Rule W1: agents read workspace artifacts; only the user changes them.
if inside(&roots.artifacts, target) {
    return Some(deny(
        WORKSPACE_ARTIFACTS,
        format!(
            "Write your result in your session dir instead of \"{raw}\": workspace artifacts belong to the user, \
             so agents read them but never write, move, or delete them. Propose a change in your report."
        ),
    ));
}

// Rule B5: the engine writes the books from the docs stage's submit calls.
if inside(&roots.books, target) {
    return Some(deny(
        WORKSPACE_DOCS,
        format!(
            "Put the documentation in your submit call instead of writing \"{raw}\": Ostra writes the \
             workspace books from the docs stage's submit calls, so agents read them but never write, move, or \
             delete them."
        ),
    ));
}

// Build streak gate (build-streak-gate.js): only the build loop itself is refused.
let command = call.str_field("command").unwrap_or_default();
if blocked && build::is_build_command(command, &self.build_commands()) {
    let submit = self.ctx.agent.submit_tool_name();
    let diag = last_sig
        .map(|s| format!(", last diagnostic: \"{s}\""))
        .unwrap_or_default();
    return Some(Denial {
        rule: RuleRef::guard(guards::BUILD_STREAK),
        reason: format!(
            "Call {submit} with status `stuck` (the STUCK: hand-back) instead of another build or test \
             command: {streak} consecutive build or test failures in this run{diag}. Retrying is not the next \
             step, because you do not yet have the information the fix needs. ..."
        ),
    });
}

#[track_caller]
fn denied(p: &ExecutionPolicy, call: &ToolCall, pattern: &str) -> String {
    let d = p.check(call);
    let reason = deny_reason(&d).unwrap_or_else(|| {
        panic!(
            "{} should be denied for {}, got {d:?}",
            call.input,
            p.ctx().agent
        )
    });
    assert!(
        reason.contains(pattern),
        "reason for {} should mention {pattern:?}: {reason}",
        call.input
    );
    reason
}

#[track_caller]
fn guard_of(p: &ExecutionPolicy, call: &ToolCall) -> String {
    match p.check(call) {
        PolicyDecision::Deny { rule, .. } => rule.rule,
        other => panic!("{} should be denied, got {other:?}", call.input),
    }
}

fn workspace_artifacts_are_read_but_never_written() {
    // Rule W1.
    let f = fx();
    let dir = ostra_core::artifacts::dir(&f.ws);
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(dir.join("sample.csv"), "a,b\n").unwrap();
    let p = f.policy(AgentName::Implementer);
    let file = dir.join("sample.csv");
    allowed(
        &p,
        &ToolCall::new("Read", json!({"file_path": file.to_string_lossy()})),
    );
    allowed(&p, &bash(format!("python3 scripts/load.py {}", shp(&file))));
    assert_eq!(guard_of(&p, &write(&file)), "workspace-artifacts");
    assert_eq!(
        guard_of(&p, &bash(format!("cp src/x {}/y.md", shp(&dir)))),
        "workspace-artifacts"
    );
    assert_eq!(
        guard_of(&p, &bash(format!("rm {}", shp(&file)))),
        "workspace-artifacts"
    );
}

let invented = f.session_dir.join("ostra-implementer-credentials-uri.md");
let r = denied(&p, &write(&invented), "declared report path");
assert!(r.starts_with("Write your report to \""));
assert!(r.contains("ostra-implementer-phase-3.md"), "{r}");

// Hardening: git metadata names programs git runs later (hooks, fsmonitor, a gitfile
// pointing at another git dir), so it changes only through git commands.
if target.components().any(|c| c.as_os_str() == ".git") {
    return Some(deny(
        GIT_METADATA,
        format!(
            "Use git commands instead of writing \"{raw}\" directly: files under .git decide which programs git \
             runs, so Ostra refuses direct writes there in every mode."
        ),
    ));
}

pub fn fit_reason(reason: &str) -> String {
    let flat = reason.split_whitespace().collect::<Vec<_>>().join(" ");
    if flat.chars().count() <= GROK_REASON_MAX {
        return flat;
    }
    let sentences: Vec<&str> = flat.split_inclusive(['.', '!', '?']).collect();
    let tail = sentences.last().map(|s| s.trim()).unwrap_or("");
    let joiner = " … ";
    let tail_len = tail.chars().count();
    let head_budget = GROK_REASON_MAX.saturating_sub(tail_len + joiner.chars().count());
    if head_budget < MIN_HEAD {
        return flat.chars().take(GROK_REASON_MAX).collect();
    }
    let head: String = flat.chars().take(head_budget).collect();
    format!("{}{joiner}{tail}", head.trim_end())
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct ToolCall {
    pub tool: String,
    #[ts(type = "unknown")]
    pub input: serde_json::Value,
}

impl ToolCall {
    pub fn new(tool: impl Into<String>, input: serde_json::Value) -> Self {
        ToolCall { tool: tool.into(), input }
    }

    pub fn str_field(&self, key: &str) -> Option<&str> {
        self.input.get(key).and_then(|v| v.as_str())
    }
}

